// fuwa-gomen / browser.js
// Generated from hooks/*.js. Do not edit this file by hand.

(function () {
	'use strict';

	function mouth() {
		return document.querySelector('#gomen [data-ref="mouth"]');
	}

	function root() {
		return document.getElementById('gomen');
	}

	function animateFly(food) {
		const gsap = window.gsap;
		const target = mouth();
		if (!gsap || !(food instanceof Element) || !(target instanceof Element)) {
			return;
		}

		const icon = food.querySelector('.fg-food-icon') || food;
		const food_rect = icon.getBoundingClientRect();
		const mouth_rect = target.getBoundingClientRect();
		const clone = icon.cloneNode(true);

		clone.style.position = 'fixed';
		clone.style.left = `${food_rect.left}px`;
		clone.style.top = `${food_rect.top}px`;
		clone.style.margin = '0';
		clone.style.zIndex = '9999';
		clone.style.pointerEvents = 'none';
		document.body.appendChild(clone);

		const dx = mouth_rect.left + mouth_rect.width / 2 - (food_rect.left + food_rect.width / 2);
		const dy = mouth_rect.top + mouth_rect.height / 2 - (food_rect.top + food_rect.height / 2);

		gsap
			.timeline({
				onComplete: function () {
					clone.remove();
					gsap.fromTo(target, { scale: 1 }, { scale: 1.12, duration: 0.21, yoyo: true, repeat: 1, ease: 'power1.inOut' });
				}
			})
			.to(clone, {
				x: dx * 0.6,
				y: dy * 0.6 - 28,
				scale: 1.4,
				duration: 0.31,
				ease: 'power1.out'
			})
			.to(clone, {
				x: dx,
				y: dy,
				scale: 0.2,
				opacity: 0,
				duration: 0.21,
				ease: 'power1.in'
			});
	}

	function animateRefusal(food) {
		const gsap = window.gsap;
		if (!gsap || !(food instanceof Element)) {
			return;
		}

		gsap.fromTo(food, { y: 0 }, { y: -8, duration: 0.08, yoyo: true, repeat: 3, ease: 'power1.out' });
	}

	function animatePoke() {
		const gsap = window.gsap;
		const target = root();
		if (!gsap || !(target instanceof Element)) {
			return;
		}

		gsap.fromTo(target, { x: 0 }, { x: -6, duration: 0.05, yoyo: true, repeat: 5, ease: 'power1.inOut' });
	}

	document.body.addEventListener('htmx:beforeRequest', function (event) {
		const target = event.target instanceof Element ? event.target : null;
		if (!target) {
			return;
		}

		const food = target.closest('.fg-food');
		if (food) {
			const current_root = root();
			const balance = current_root ? Number(current_root.dataset.balance || '0') : 0;
			const price = Number(food.getAttribute('data-price') || '0');
			if (balance < price) {
				animateRefusal(food);
				return;
			}
			animateFly(food);
			return;
		}

		const action = target.closest('[data-action="poke"]');
		if (action) {
			animatePoke();
		}
	});
})();
